import sys

def main():
    input = sys.stdin.readline
    H, W = map(int, input().split())

    grid = []
    min_r, max_r = H, -1
    min_c, max_c = W, -1

    for i in range(H):
        s = input().strip()
        grid.append(s)
        for j, ch in enumerate(s):
            if ch == '#':
                if i < min_r:
                    min_r = i
                if i > max_r:
                    max_r = i
                if j < min_c:
                    min_c = j
                if j > max_c:
                    max_c = j

    for i in range(min_r, max_r + 1):
        if grid[i].find('.', min_c, max_c + 1) != -1:
            print("No")
            return

    print("Yes")

if __name__ == "__main__":
    main()

