import sys

def main():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    s = data[1]
    q = []
    cnt = 0

    for i, ch in enumerate(s):
        if ch == 49:  # ord('1')
            q.append(i - cnt)
            cnt += 1

    if cnt <= 1:
        print(0)
        return

    median = q[cnt // 2]
    ans = sum(abs(x - median) for x in q)
    print(ans)

if __name__ == "__main__":
    main()
